{"content":"import json, csv, os
import numpy as np
from ase.io import read
from ase import units
from ase.neighborlist import neighbor_list
base='output/verified_md/call_7HtnzmzMhsLpBtKGdqhvcXQ8'
out='output/submission'
os.makedirs(out,exist_ok=True)
frames=read(base+'/production.traj',':')
stage_ids=['initial_300K','forward_400K','forward_500K','forward_600K','forward_700K','forward_800K','forward_900K','return_300K']
rows={s:[] for s in stage_ids}
coords={s:[] for s in stage_ids}
for a in frames:
 s=a.info['stage']; p=a.get_momenta(); m=a.get_masses()[:,None]
 keaxis=(p*p/(2*m)).sum(axis=0)
 tdir=2*keaxis/(len(a)*units.kB)
 ke=keaxis.sum(); pe=a.get_potential_energy(); temp=2*ke/(3*len(a)*units.kB)
 rows[s].append((a.info['time_fs'],temp,*tdir,(pe+ke)/len(a),pe,ke))
 i=neighbor_list('i',a,3.3); coord=np.bincount(i,minlength=len(a))
 coords[s].append(float(coord.mean()))
results={}
for s in stage_ids:
 x=np.array(rows[s]); results[s]={'temperature_mean_K':float(x[:,1].mean()),'directional_temperature_mean_K':[float(v) for v in x[:,2:5].mean(axis=0)],'energy_mean_eV_per_atom':float(x[:,5].mean())}
fitids=stage_ids[:5]
T=np.array([results[s]['temperature_mean_K'] for s in fitids]); E=np.array([results[s]['energy_mean_eV_per_atom'] for s in fitids])
slope,intercept=np.polyfit(T,E,1)
res={s:results[s]['energy_mean_eV_per_atom']-(slope*results[s]['temperature_mean_K']+intercept) for s in stage_ids[5:7]}
# equilibration evidence from provided trace: compare means of first and second halves (5 each)
eq={s:[] for s in stage_ids}
with open(base+'/equilibration_trace.csv') as f:
 for r in csv.DictReader(f): eq[r['stage']].append(float(r['kinetic_temperature_K']))
eqev={}
for s,v in eq.items():
 eqev[s]={'target_temperature_K':dict(zip(stage_ids,[300,400,500,600,700,800,900,300]))[s], 'first_half_temperature_mean_K':float(np.mean(v[:5])),'second_half_temperature_mean_K':float(np.mean(v[5:])), 'last_equilibration_sample_K':float(v[-1]),'production_temperature_mean_K':results[s]['temperature_mean_K']}
ret={'energy_difference_eV_per_atom':results['return_300K']['energy_mean_eV_per_atom']-results['initial_300K']['energy_mean_eV_per_atom'], 'initial_structural_mean':float(np.mean(coords['initial_300K'])),'return_structural_mean':float(np.mean(coords['return_300K']))}
ret['structural_difference']=ret['return_structural_mean']-ret['initial_structural_mean']
analysis={'stage_statistics':results,'fit':{'method':'unweighted ordinary least squares on five stage-level production means; predictor is measured kinetic temperature and response is total energy per atom','stage_ids':fitids,'slope_eV_per_atom_K':float(slope),'intercept_eV_per_atom':float(intercept),'value_kB_per_atom':float(slope/units.kB)},'high_temperature_residuals_eV_per_atom':res,'return_state':ret,'structure_metric':{'method':'mean per-atom coordination number using ASE periodic neighbor list','cutoff_A':3.3,'window':'all retained production frames, identically for both 300 K stages'},'equilibration_evidence':eqev,'sampling':{'production_interval_steps':100,'production_frames_per_stage':51,'equilibration_interval_steps':500,'equilibration_samples_per_stage':10,'note':'Production includes both window endpoints.'}}
with open(out+'/analysis.json','w') as f: json.dump(analysis,f,indent=2)
print(json.dumps(analysis,indent=2))
","path":"/workspace/analyze.py"}

