import pandas as pd, numpy as np, json, os, platform
O='output'
stages=[]
for name in ['cooling','hold','reheating']:
 d=pd.read_csv(f'{O}/{name}.csv')
 for _,r in d.iterrows():
  stages.append({'stage':name,'step':int(r.Step),'time_ps':float(r.Time/1000),'target_temperature_K':float(r.v_Ttarget),'temperature_K':float(r.Temp),'pressure_atm':float(r.Press),'density_g_cm3':float(r.Density)})
with open(f'{O}/thermal_trace.json','w') as f: json.dump(stages,f,indent=2)

def transition(name):
 d=pd.read_csv(f'{O}/{name}.csv'); sel=d[(d.Temp>=350)&(d.Temp<=1250)].copy(); x=sel.Temp.to_numpy(); y=sel.Density.to_numpy()
 candidates=np.arange(550.,1050.1,1.)
 ss=[]
 for t in candidates:
  X=np.c_[np.ones(len(x)),x,np.maximum(0,x-t)]
  coef=np.linalg.lstsq(X,y,rcond=None)[0]; ss.append(np.sum((y-X@coef)**2))
 t=float(candidates[np.argmin(ss)]); X=np.c_[np.ones(len(x)),x,np.maximum(0,x-t)]; coef=np.linalg.lstsq(X,y,rcond=None)[0]
 return t, {'method':'continuous_piecewise_linear_hinge_least_squares','temperature_coordinate':'measured temperature_K','data_stage':name,'data_filter_K':{'minimum':350.0,'maximum':1250.0},'indices_in_stage_trace':[int(i) for i in sel.index], 'step_range':[int(sel.Step.min()),int(sel.Step.max())], 'time_range_ps':[float(sel.Time.min()/1000),float(sel.Time.max()/1000)],'candidate_breakpoints_K':{'minimum':550.0,'maximum':1050.0,'spacing':1.0},'estimate_K':t,'fit_coefficients_density_equals_a_plus_bT_plus_c_max0_TminusTg':[float(z) for z in coef], 'n_points':len(sel),'sampling_interval_steps':100}
cool,ca=transition('cooling'); heat,ha=transition('reheating')
h=pd.read_csv(f'{O}/hold.csv'); h['ps']=h.Time/1000
# discard first 2 ps; use 22-30 for representative mean and drift
q=h[(h.ps>=22)&(h.ps<=30)]; slope,inter=np.polyfit(q.ps,q.Density,1)
hold={'mean_window_ps':[22.0,30.0],'indices_in_hold_trace':[int(i) for i in q.index], 'step_range':[int(q.Step.min()),int(q.Step.max())], 'n_points':len(q),'mean_temperature_K':float(q.Temp.mean()),'mean_density_g_cm3':float(q.Density.mean()),'drift_window_ps':[22.0,30.0],'drift_indices_in_hold_trace':[int(i) for i in q.index], 'drift_method':'ordinary_least_squares density versus elapsed time','density_drift_g_cm3_ps':float(slope),'density_intercept_g_cm3':float(inter),'window_justification':'The first 2 ps of the short hold were discarded as immediate ramp-to-hold/barostat transient; all remaining 8 ps were used for both representative means and drift.'}
analysis={'transitions':{'cooling':ca,'reheating':ha},'signed_difference_reheating_minus_cooling_K':heat-cool,'hold':hold,'assessment':{'equilibration_evidence':'Over 22-30 ps the fitted density slope is small relative to the mean density, while measured temperature averages near the 300 K target. Instantaneous pressure, temperature, and density remain noisy for this 192-atom cell. A nonzero fitted drift and the sensitivity expected from a short window do not establish full equilibration.','limitations':'The 50 K/ps ramps are many orders faster than laboratory scans and the 10 ps hold is too short for structural relaxation of a silicate glass. The inferred breakpoints are protocol- and estimator-dependent kinetic crossover temperatures, not equilibrium thermodynamic Tg values. Finite-size fluctuations and NPT barostat lag further limit interpretation. Only one trajectory was run, so no ensemble uncertainty is available.'}}
with open(f'{O}/analysis.json','w') as f: json.dump(analysis,f,indent=2)
bs={}
for key,time,file in [('initial',0,'initial.data'),('cooling_end',20,'cooling_end.data'),('hold_start',20,'hold_start.data'),('hold_end',30,'hold_end.data'),('reheating_start',30,'reheating_start.data'),('reheating_end',50,'reheating_end.data')]:
 bs[key]={'time_ps':float(time),'step':int(time*1000),'lammps_data':file,'lammps_restart':file.replace('.data','.restart'),'atom_style':'charge','atom_type_species':{'1':'Na','2':'Si','3':'O'},'preserves':'cell, atom IDs, positions, charges, velocities, and elapsed timestep'}
with open(f'{O}/boundary_states.json','w') as f: json.dump(bs,f,indent=2)
settings={'units':'real','atom_style':'charge','boundary':'p p p','potential':'BKS-type Buckingham-Coulomb from input/pot.mod','potential_file':'../input/pot.mod','pair_style':'hybrid/overlay buck/coul/long 8.0 12.0','kspace_style':'pppm 1.0e-4','software_versions':{'LAMMPS':'22 Jul 2025'},'simulation':{'initial_state':'../input/liq1300.dat','atom_count':192,'timestep_fs':1.0,'ensemble':'isotropic NPT throughout','target_pressure_atm':0.0,'integrator_thermostat_barostat':'LAMMPS fix npt (Nosé-Hoover time integration, thermostat, and isotropic barostat)','thermostat_damping_fs':100.0,'barostat_damping_fs':1000.0,'velocity_policy':'Read supplied velocities; never reinitialized','stages':[{'name':'cooling','steps':20000,'target_temperature_K':[1300,300]},{'name':'hold','steps':10000,'target_temperature_K':[300,300]},{'name':'reheating','steps':20000,'target_temperature_K':[300,1300]}],'thermo_sampling_steps':100,'thermo_sampling_ps':0.1,'neighbor':'2.0 A bin; every 1 delay 0 check yes'},'analysis_summary':{'transition_estimator':'continuous two-slope piecewise-linear hinge regression of density against measured temperature; breakpoint grid minimizes SSE','transition_data_range_measured_K':[350,1250],'breakpoint_search_K':[550,1050],'breakpoint_spacing_K':1.0,'hold_analysis_window_ps':[22,30]}}
