manifest={'results':{'cooling_tg_K':cool,'reheating_tg_K':heat,'delta_tg_K':heat-cool,'hold_temperature_K':hold['mean_temperature_K'],'hold_density_g_cm3':hold['mean_density_g_cm3'],'hold_density_drift_g_cm3_ps':hold['density_drift_g_cm3_ps'],'units':{'temperature':'K','density':'g/cm3','density_drift':'g/cm3/ps'}},'artifacts':arts,'settings':'settings.json','scripts':['../make_submission.py']}
