{"content":"import json, hashlib, os
import numpy as np
from ase.build import bulk
from mace.calculators import MACECalculator
OUT='/workspace/task8'; os.makedirs(OUT,exist_ok=True)
seeds={'train':81231,'id_test':81232,'strained_test':81233}
ideal=bulk('Si','diamond',a=5.43,cubic=True).repeat((2,2,2))

def frame(a,row,sigma,strain,idx,energy=None):
 d={'symbols':a.get_chemical_symbols(),'positions_A':a.positions.tolist(),'cell_A':a.cell.array.tolist(),'pbc':[True]*3,'info':{'row_id':row,'generation_index':idx,'sigma_A':sigma,'strain':strain}}
 if energy is not None:d['potential_energy_eV']=float(energy)
 return d
# exact replay rule: fresh default_rng, one (64,3) draw per frame, sequentially
rng=np.random.default_rng(seeds['train']); train=[]; atoms=[]
for i in range(100):
