atoms=[Atoms(x['symbols'],positions=x['positions_A'],cell=x['cell_A'],pbc=x['pbc']) for x in frames]
descs={
 'soap_r4_n4_l3':dict(species=['Si'],periodic=True,r_cut=4.0,n_max=4,l_max=3,sigma=0.5,average='inner',sparse=False),
 'soap_r5_n6_l4':dict(species=['Si'],periodic=True,r_cut=5.0,n_max=6,l_max=4,sigma=0.5,average='inner',sparse=False)}
Xs={k:SOAP(**p).create(atoms,n_jobs=1) for k,p in descs.items()}
# deterministic interleaved folds: every fold spans full schedule
folds=[]
for f in range(5):
 va=np.arange(f,100,5); tr=np.setdiff1d(np.arange(100),va); folds.append((tr,va))
alphas=[1e-6,1e-4,1e-2,1.,100.]
def metrics(a,b):return {'mae':float(mean_absolute_error(a,b)),'rmse':float(mean_squared_error(a,b)**.5),'r2':float(r2_score(a,b))}
records=[]; summary={}
for did,X in Xs.items():
 for alpha in alphas:
  cid=f'{did}_alpha_{alpha:g}'; pred=np.empty(100)
  for f,(tr,va) in enumerate(folds):
   sc=StandardScaler().fit(X[tr]); m=Ridge(alpha=alpha).fit(sc.transform(X[tr]),y[tr]); pv=m.predict(sc.transform(X[va])); pred[va]=pv
