json.dump(validation,open(OUT+'/validation.json','w'),indent=2)
# frozen nested, distribution-spanning subsets: nearest evenly spaced ranks; same subsets used in later ID test learning curve
sizes=[20,40,60,80,100]; subsets={}
for n in sizes:
 idx=np.unique(np.round(np.linspace(0,99,n)).astype(int)); assert len(idx)==n; subsets[str(n)]=idx.tolist()
