{"content":"import json, os, itertools
import numpy as np
from scipy.special import sph_harm
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import Ridge
from sklearn.metrics import mean_absolute_error,mean_squared_error,r2_score
from ase.io import read
from ase import Atoms

OUT='output'; names=['main','independent_800','independent_500','independent_1100']
# SOAP power spectrum: smooth neighbor density, Gaussian radial channels, spherical-harmonic power, global mean.
RC=5.0; NMAX=6; LMAX=4; SIG=0.5; centers=np.linspace(0,RC,NMAX)

def soap_frame(fr):
 p=np.asarray(fr['positions_A']); cell=np.asarray(fr['cell_A']); n=len(p)
 shifts=np.array(list(itertools.product(range(-1,2),repeat=3)))@cell
 feats=[]
 for i in range(n):
  vec=(p[None,:,:]+shifts[:,None,:]-p[i]).reshape(-1,3)
  r=np.linalg.norm(vec,axis=1); keep=r<RC; vec=vec[keep]; r=r[keep]
  # include central atom; smooth cosine cutoff
  w=np.exp(-0.5*((r[:,None]-centers[None,:])/SIG)**2)*(0.5*(np.cos(np.pi*r[:,None]/RC)+1))
  theta=np.zeros_like(r); nz=r>1e-12; theta[nz]=np.arccos(np.clip(vec[nz,2]/r[nz],-1,1)); phi=np.arctan2(vec[:,1],vec[:,0])
  one=[]
  for l in range(LMAX+1):
   C=np.empty((NMAX,2*l+1),complex)
   for mi,m in enumerate(range(-l,l+1)): C[:,mi]=(w*sph_harm(m,l,phi,theta)[:,None]).sum(axis=0)
   P=(C@C.conj().T).real
   one.extend(P[np.triu_indices(NMAX)].tolist())
  feats.append(one)
 return np.mean(feats,axis=0)

frames={}; X={}; y={}
for name in names:
 with open(f'{OUT}/{name}.trajectory.json') as f: frames[name]=json.load(f)
 X[name]=np.array([soap_frame(z) for z in frames[name]])
 y[name]=np.array([z['potential_energy_eV'] for z in frames[name]])
 with open(f'{OUT}/{name}.descriptors.json','w') as f: json.dump(X[name].tolist(),f,separators=(',',':'))
 # remove non-applicable placeholder pressure from logs
 lp=f'{OUT}/{name}.log.json'; log=json.load(open(lp))
 for z in log: z.pop('pressure_GPa',None)
 json.dump(log,open(lp,'w'),separators=(',',':'))
